  let titleEl = row.querySelector('.row-title');
  if (titleEl) {
    pages.push({
      title: titleEl.textContent.trim(),
      status: row.querySelector('.post-state')?.textContent.trim() || 'published',
      date: row.querySelector('.date')?.textContent.trim() || ''
    });
  }
});
